layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 4px solid rgb(231, 234, 240); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 1.8px; padding-top: 18px; padding-right: 18px; padding-bottom: 18px; padding-left: 18px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgba(2, 154, 232, 0.5); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-radius: 4.5px; box-shadow: rgba(129, 145, 181, 0.016) 0.261px 0.522px 3.132px 0px, rgba(129, 145, 181, 0.024) 0.603px 1.206px 7.236px 0px, rgba(129, 145, 181, 0.03) 1.125px 2.25px 13.5px 0px, rgba(129, 145, 181, 0.035) 2.025px 4.05px 24.3px 0px, rgba(129, 145, 181, 0.043) 3.753px 7.506px 45.036px 0px, rgba(129, 145, 181, 0.06) 9px 18px 108px 0px, rgba(129, 145, 181, 0.016) 0px 0px 0px 1.125px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 50%, transparent); text-decoration-thickness: auto; text-underline-offset: 2.25px; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out, text-decoration 0.2s ease-in-out, box-shadow 0.2s ease-in-out }
[data-ryt="nav"] a { color: #878a8f; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: 1.8px; padding-top: 0px; padding-right: 18px; padding-bottom: 0px; padding-left: 18px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 1.8px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 1.8px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 50%, transparent); text-decoration-thickness: auto; text-underline-offset: 4.5px; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out, text-decoration 0.2s ease-in-out, box-shadow 0.2s ease-in-out }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(45, 49, 56); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 700; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(45, 49, 56); text-decoration-thickness: auto; text-underline-offset: 1.8px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { opacity: 1 }
body:hover { opacity: 1 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { opacity: 1 }
[data-ryt="credit"]:hover, [data-ryt="eyebrow"]:hover { opacity: 1 }
[data-ryt="review"]:hover { opacity: 1 }
[data-ryt="nav"] a:hover { opacity: 1 }
[data-ryt="header"]:hover { opacity: 1 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { opacity: 1 }
article[data-ryt="rec-card"]:hover { opacity: 1 }
[data-ryt="footer"]:hover { opacity: 1 }
[data-ryt="pitch"]:hover { opacity: 1 }
